# What a test rewinding a head file drops: the guards, then the tables (children first).
TRIGGERS = tuple(statement.split()[2] for statement in GUARDS)
_ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'


def _ulid():
    value = (int(time.time() * 1000) << 80) | int.from_bytes(os.urandom(10), 'big')
    return ''.join(_ALPHABET[(value >> (5 * (25 - n))) & 31] for n in range(26))


def upgrade():
    db = op.get_bind()
    names = {row[0].casefold() for row in db.exec_driver_sql('SELECT name FROM sqlite_schema')}
    if names & (set(TABLES) | set(TRIGGERS)):
        raise RuntimeError('co0105 reserved object exists')
    for statement in DDL + INDEXES + COLUMNS:
        db.exec_driver_sql(statement)
    now = time.strftime('%Y-%m-%dT%H:%M:%S.000Z', time.gmtime())
    for kind, name, subject, body in SEEDED_TEMPLATES:
        db.exec_driver_sql(
            "INSERT INTO delivery_templates (id, version, created_at, created_by, created_via, updated_at, updated_by, "
            "updated_via, kind, name, name_key, subject, body, is_default, active) "
            "VALUES (?, 1, ?, 'system', 'migration', ?, 'system', 'migration', ?, ?, ?, ?, ?, 1, 1)",
            (_ulid(), now, now, kind, name, name.casefold(), subject, body))
    for statement in GUARDS:
        db.exec_driver_sql(statement)
    if db.exec_driver_sql('PRAGMA foreign_key_check').first():
        raise RuntimeError('co0105 foreign key check failed')


def downgrade():
    raise RuntimeError('Company migrations are forward-only')
